{"command":"python3 -c "
import csv

# Get all stop data from clean stops
stops_clean = {}
with open('outputs/t05_clean_stops.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stops_clean[row['stop_id']] = {
            'stop_name': row['stop_name'],
            'stop_lat': row['stop_lat'],
            'stop_lon': row['stop_lon']
        }

# Check output
errors = []
with open('outputs/t06_stop_service_intensity.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_id = row['stop_id']
        if stop_id in stops_clean:
            clean = stops_clean[stop_id]
            if row['stop_name'] != clean['stop_name']:
                errors.append(f'{stop_id}: stop_name mismatch')
            if row['stop_lat'] != clean['stop_lat']:
                errors.append(f'{stop_id}: stop_lat mismatch')
            if row['stop_lon'] != clean['stop_lon']:
                errors.append(f'{stop_id}: stop_lon mismatch')
        else:
            errors.append(f'{stop_id}: not in clean stops')

if errors:
    print('Errors found:')
    for e in errors[:10]:
        print(e)
else:
    print('All stop_name, stop_lat, stop_lon values match!')
""}

